/** @return string Lucide icon name for a menu path */
function ui_menu_icon(string $path): string
{
    $map = [
        '/' => 'house',
        '/orders' => 'package',
        '/customers' => 'users',
        '/board' => 'scissors',
        '/work-orders' => 'scissors',
        '/products' => 'shirt',
        '/stock' => 'boxes',
        '/sales' => 'receipt',
        '/purchasing' => 'shopping-cart',
        '/expenses' => 'wallet',
        '/outstanding' => 'wallet',
        '/reports' => 'chart-column',
        '/branches' => 'map-pin',
        '/staff' => 'user-lock',
        '/account/subscription' => 'crown',
        '/settings' => 'settings',
        '/messages' => 'mail',
        '/calendar' => 'calendar',
        '/more' => 'ellipsis',
        '/groups' => 'users',
        '/broadcasts' => 'mail',
        '/platform' => 'house',
        '/platform/tenants' => 'users',
        '/platform/plans' => 'crown',
        '/platform/payments' => 'credit-card',
        '/platform/gateway' => 'settings',
    ];
    return $map[$path] ?? 'ellipsis';
}
